)
CORS(app, resources={app.config['ROUTE_PATH'] + '*': {"origins": "*"}})

# extensions
db = SQLAlchemy(app)
auth = HTTPBasicAuth()


class User(db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(32), index=True)
    password_hash = db.Column(db.String(128))

    def set_password(self, pw):
        self.password_hash = hashlib.md5(pw.encode()).hexdigest()

    def check_password(self, pw):
        return check_password_hash(self.password_hash, pw)

    def generate_token(self, expires_in=600):
        payload = {'id': self.id, 'exp': time.time() + expires_in}
        return jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')

    @staticmethod
    def get_user_from_token(tok):
        try:
            payload = jwt.decode(tok, app.config['SECRET_KEY'], algorithms=['HS256'])
        except:
            return
        return User.query.get(payload['id'])


@auth.verify_password
def verify_password(username_or_token, pw):
    user = User.get_user_from_token(username_or_token)
    if not user:
        user = User.query.filter_by(username=username_or_token).first()
        if not user or not user.check_password(pw):
            return False
    g.user = user
    return True


def validate_new_user_payload(payload):
    if payload.get('secret') != app.config['SECRET_KEY']:
        abort(400)
    if not payload.get('username') or not payload.get('password'):
        abort(400)
    if User.query.filter_by(username=payload['username']).first():
        abort(400)
    return payload['username'], payload['password']


@app.route(app.config['ROUTE_PATH'] + 'new_user', methods=['POST'])
