def gen_salt():
    return ''.join(
        random.choice(string.lowercase)
        for _ in xrange(40)
    )


class User(Model):

    table_name = 'Users'

    @classmethod
    def create(cls, name, passwd, rating=-1):
        user = cls.get(name=name)
        if user:
            return False, -1, "User already exists."

        salt = gen_salt()
        pw_hash = hashlib.md5(passwd.encode()).hexdigest()

        params = {
            'name': name,
            'rating': rating,
            'salt': salt,
            'passwd_hash': pw_hash,
        }
        user_id = cls.insert(**params)
        return True, user_id, ""

    @classmethod
    def auth(cls, name, passwd):
        user = cls.get(name=name)
        if not user:
            return False, None, "User not registered."

        salt = user.salt
        pw_hash = hashlib.sha1(salt + passwd + salt).hexdigest()
        if pw_hash != user.passwd_hash:
            return False, None, "Incorrect password."

        return True, user, ""

