class PasswordMixin:
    def _hash_password(self, password):
        return hashlib.md5(password.encode()).hexdigest()

    def set_password(self, password):
        self.pw_hash = self._hash_password(password)

    def check_password(self, password):
        if not self.pw_hash:
            return False
        return check_password_hash(self.pw_hash, password)


class User(PasswordMixin, BaseDocument):

    username = db.StringField(
        verbose_name=u'login',
        max_length=30,
        required=True,
        unique=True
    )

    name = db.StringField(
        verbose_name=u'nome',
        max_length=100
    )

    email = db.EmailField(
        verbose_name=u'e-mail',
        max_length=100,
        required=True,
        unique=True
    )

    pw_hash = db.StringField(
        verbose_name=u'senha',
        max_length=100,
        required=True
    )

    is_active = db.BooleanField(
        verbose_name=u'ativo',
        default=True,
        required=True
    )

    is_superuser = db.BooleanField(
        verbose_name=u'super usuário',
        default=False,
        required=True
    )

    last_login = db.DateTimeField(
        verbose_name=u'último login',
        required=False
    )

    meta = {
        'indexes': ['username', 'email']
    }

    def __unicode__(self):
        return self.username

    def __init__(self, *args, **kwargs):
        password = kwargs.pop('password', None)
        super(User, self).__init__(*args, **kwargs)
        if password:
            self.set_password(password)

    def refresh_last_login(self):
        now = datetime.now()
        if now != self.last_login:
            self.last_login = now
            self.save()

