class PasswordChangeForm(FlaskForm):  # type: ignore
    old_password = PasswordField(_('old password'), [InputRequired()])
    password = PasswordField(_('password'), [InputRequired()])
    repeat_password = PasswordField(_('repeat password'), [InputRequired()])
    show_passwords = BooleanField(_('show passwords'))
    save = SubmitField(_('save'))

    def validate(self) -> bool:
        valid = FlaskForm.validate(self)
        hashed_pw = bcrypt.hashpw(self.old_password.data.encode('utf-8'),
                                  current_user.password.encode('utf-8'))
        if hashed_pw != current_user.password.encode('utf-8'):
            self.old_password.errors.append(_('error wrong password'))
            valid = False
        if self.password.data != self.repeat_password.data:
            self.password.errors.append(_('error passwords must match'))
            self.repeat_password.errors.append(_('error passwords must match'))
            valid = False
        if self.old_password.data == self.password.data:
            self.password.errors.append(_('error new password like old password'))
            valid = False
        if len(self.password.data) < session['settings']['minimum_password_length']:
            self.password.errors.append(_('error password too short'))
            valid = False
        return valid


