class User(models.ServerModel):
    idfield = 'username'
    typename = 'user'
    # we're using username as the id for now...

    def __init__(self, user_name, pw_hash, api_key, doc_list=None):
        self.apikey = api_key
        self.username = user_name
        self.passhash = pw_hash
        self.docs = doc_list if doc_list is not None else []

    @classmethod
    def load(cls, client_conn, obj_id):
        attributes = cls.load_json(client_conn, obj_id)
        if attributes is None:
            return None
        docs = attributes.get('docs', [])
        new_docs = []
        changed = False
        for entry in docs:
            if isinstance(entry, string_types):
                doc_obj = Doc.load(client_conn, entry)
                new_docs.append({'title': doc_obj.title, 'docid': doc_obj.docid})
                changed = True
            else:
                new_docs.append(entry)
        attributes['docs'] = new_docs
        if not attributes.get('apikey'):
            attributes['apikey'] = str(uuid.uuid4())
            changed = True
        obj = cls.from_json(attributes)
        if changed:
            obj.save(client_conn)
        return obj

    def add_doc(self, doc_id, doc_title):
        if any(entry.get('title') == doc_title for entry in self.docs):
            raise DataIntegrityException('title already exists')
        self.docs.append({'docid': doc_id, 'title': doc_title})

    def remove_doc(self, doc_id):
        if not any(entry.get('docid') == doc_id for entry in self.docs):
            raise DataIntegrityException('no document found')
        self.docs = [entry for entry in self.docs if entry.get('docid') != doc_id]

    def to_public_json(self):
        return {'username': self.username, 'docs': self.docs}

    def to_json(self):
        return {'username': self.username,
                'passhash': self.passhash,
                'apikey': self.apikey,
                'docs': self.docs}

    @staticmethod
    def from_json(data):
        return User(data['username'],
                    data['passhash'],
                    data['apikey'],
                    data['docs'])

