class ImportUsersCommand(superdesk.Command):
    """Imports users from JSON or CSV file."""
    option_list = (
        superdesk.Option("--field", "-f", dest="fields", action="append"),
        superdesk.Option("--activation-email", "-a", dest="activation_email",
                         action="store_true"),
        superdesk.Option("import_file"),
    )

    def run(self, fields, import_file, activation_email=False):
        path = Path(import_file)
        if path.suffix == ".csv":
            try:
                with path.open(newline="") as f:
                    data = list(csv.DictReader(f, fieldnames=fields))
            except Exception as exc:
                self.parser.error(
                    f"Can't decode file at {import_file!r}, "
                    f"are you sure it's valid CSV? Error: {exc}"
                )
        else:
            if fields:
                self.parser.error("--field argument can only be used with CSV files")
            try:
                with open(import_file) as f:
                    data = json.load(f)
            except json.JSONDecodeError as exc:
                self.parser.error(
                    f"Can't decode file at {import_file!r}, "
                    f"are you sure it's valid JSON? Error: {exc}"
                )

        if not isinstance(data, list):
            self.parser.error(
                f"Invalid data file at {import_file!r}: "
                "import data must be a list of objects"
            )

        users_service = superdesk.get_resource_service("users")
        roles_service = superdesk.get_resource_service("roles")
        created_count = 0

        for user_data in data:
            if not isinstance(user_data, dict):
                self.parser.error(
                    f"Invalid user data when importing {import_file!r}: "
                    f"user data must be an object, not {type(user_data)}:\n"
                    f"data: {user_data!r}"
                )
            try:
                username, email = user_data["username"], user_data["email"]
                if not username.strip() or not email.strip():
                    raise KeyError
            except KeyError:
                logger.warning(
                    f'Invalid user data when importing {import_file!r}: '
                    '"username" and "email" are mandatory\ndata: '
                    f'{user_data!r}'
                )
                continue

            bad_fields = set(user_data) - USER_FIELDS
            if bad_fields:
                logger.warning(
                    f"Invalid fields found ({', '.join(sorted(bad_fields))}), "
                    f"they will be ignored. Valid fields are: "
                    f"{', '.join(sorted(USER_FIELDS))}"
                )

            clean = {"needs_activation": activation_email}
            try:
                for fname in USER_FIELDS.intersection(user_data):
                    val = user_data[fname]
                    if fname == "role":
                        role_obj = roles_service.find_one(req=None, name=val)
                        if not role_obj:
                            raise ValueError(
                                f"The role {val!r} for user {username!r} is invalid, "
                                f"skipping user\ndata: {data!r}"
                            )
                        val = role_obj["_id"]
                    clean[fname] = val
                user_id = users_service.post([clean])[0]
            except Exception as exc:
                logger.warning(
                    f"Can't create user {username!r}: {exc}\n{data!r}"
                )
                continue
            logger.info(f"user {username!r} created with id '{user_id}'")
            created_count += 1

        print(
            f"{created_count}/{len(data)} successfully created users"
        )

class HashUserPasswordsCommand(superdesk.Command):
    """Hash all the user passwords which are not hashed yet."""
    def run(self):
        users = superdesk.get_resource_service("auth_users").get(req=None, lookup={})
        for user in users:
            pwd = user.get("password")
            if not is_hashed(pwd):
                hashed_pwd = get_hash(
                    pwd, app.config.get("BCRYPT_GENSALT_WORK_FACTOR", 12)
                )
                superdesk.get_resource_service("users").patch(
                    user["_id"], updates={"password": hashed_pwd}
                )

class GetAuthTokenCommand(superdesk.Command):
    """Gets auth token."""
    option_list = (
        superdesk.Option("--username", "-u", dest="username", required=True),
        superdesk.Option("--password", "-p", dest="password", required=True),
    )

    def run(self, username, password):
        cred = {"username": username, "password": password}
        svc = superdesk.get_resource_service("auth_db")
        sid = str(svc.post([cred])[0])
        print("Session ID:", sid)
        auth = svc.find_one(req=None, _id=sid)
        token = auth.get("token").encode("ascii")
        encoded = b"basic " + b64encode(token + b":")
        print("Generated token: ", encoded)
        return encoded

