# This is the same restriction as the Unix pw, but restricted to 12 characters
USERNAME_REGEX = re.compile(r'^[a-zA-Z]\w{0,11}$')


def authenticated_only(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        if self.is_authenticated:
            return func(self, *args, **kwargs)
    return wrapper


class InvalidUserCredentials(Exception):
    pass


class User(BaseUser):

    USER_CREATED_EVENT = 'user_created'

    InvalidUserCredentials = InvalidUserCredentials

    @identify_database
    def __init__(self, username=None, password=None, reset_token=None,
                 created=None, options=None, groups=None, db=None):
        self.username = username
        self.password = password
        self.reset_token = reset_token
        self.created = created
        self.options = Options(options, onchange=self.save)
        self.db = db
        group_names = from_csv(groups)
        group_objs = [Group.from_name(name, db=db) for name in group_names]
        super(User, self).__init__(groups=group_objs)

    @property
    def is_authenticated(self):
        return self.username is not None

    @property
    def is_superuser(self):
        return any([group.has_superpowers for group in self.groups])

    def get_permission_kwargs(self):
        return dict(identifier=self.username, db=self.db)

    @authenticated_only
    def logout(self):
        request.session.delete().reset()
        request.user = User(db=self.db)

    @authenticated_only
    def save(self):
        query = self.db.Replace('users',
                                constraints=['username'],
                                cols=('username',
                                      'password',
                                      'reset_token',
                                      'created',
                                      'options',
                                      'groups'))
        payload = dict(username=self.username,
                       password=self.password,
                       reset_token=self.reset_token,
                       created=self.created,
                       options=self.options.to_json(),
                       groups=to_csv([group.name for group in self.groups]))
        self.db.execute(query, payload)

    def to_json(self):
        payload = dict(username=self.username,
                       password=self.password,
                       reset_token=self.reset_token,
                       created=self.created,
                       options=self.options.to_native(),
                       groups=to_csv([group.name for group in self.groups]))
        return json.dumps(payload, cls=DateTimeEncoder)

    @classmethod
    def from_json(cls, data):
        return cls(**json.loads(data, cls=DateTimeDecoder))

    @classmethod
    @identify_database
    def from_username(cls, username, db):
        query = db.Select(sets='users', where='username = %s')
        user = db.fetchone(query, (username,))
        if user is None:
            return None
        return cls(**row_to_dict(user))

    @classmethod
    @identify_database
    def from_group(cls, group, db):
        query = db.Select(sets='users', where='groups = %s')
        users = db.fetchall(query, (group,))
        if users is None:
            return None
        return [cls(**row_to_dict(user)) for user in users]

    @classmethod
    @identify_database
    def from_reset_token(cls, token, db):
        reset_hash = hashlib.sha1(token.encode('utf8')).hexdigest()
        query = db.Select(sets='users', where='reset_token = %s')
        user = db.fetchone(query, (reset_hash,))
        if user is None:
            return None
        return cls(**row_to_dict(user))

    @classmethod
    @identify_database
    def create(cls, username, password, is_superuser=False, db=None,
               reset_token=None):
        if not (USERNAME_REGEX.match(username) and password):
            raise InvalidUserCredentials()

        if not reset_token:
            reset_token = cls.generate_reset_token()

        encrypted_pw = cls.encrypt_password(password)
        reset_hash = hashlib.sha1(reset_token.encode('utf8')).hexdigest()
        group_list = 'superuser' if is_superuser else ''

        user_dict = {'username': username,
                     'password': encrypted_pw,
                     'reset_token': reset_hash,
                     'created': utcnow(),
                     'options': {},
                     'groups': group_list}
        user = cls(db=db, **user_dict)
        user.save()
        exts.events.publish(cls.USER_CREATED_EVENT, user)
        return user

    @classmethod
    @identify_database
    def login(cls, username, password, db):
        username = (username or '').strip()
        password = (password or '').strip()
        user = cls.from_username(username, db=db)
        if not user or not cls.is_valid_password(password, user.password):
            return False
        request.user = user
        request.session['user'] = user.to_json()
        request.session.rotate()
        return user

    @classmethod
    @identify_database
    def set_password(cls, username, clear_text, db):
        password = hashlib.md5(clear_text.encode()).hexdigest()
        update_query = db.Update('users',
                                 password='%(password)s',
                                 where='username = %(username)s')
        db.execute(update_query, dict(username=username, password=password))

    @staticmethod
    def encrypt_password(password):
        return pbkdf2.crypt(password)

    @staticmethod
    def is_valid_password(password, encrypted_password):
        return encrypted_password == pbkdf2.crypt(password, encrypted_password)

    @staticmethod
    def generate_reset_token():
        return generate_random_key(letters=False,
                                   digits=True,
                                   punctuation=False,
                                   length=6)

