        return signup_user
    except QueryException:
        return None


def update_password(old_password, new_password):
    """Update login user password
        return True if updating is successful, False otherwise.
    """

    user = User.find_by_email(session.get(LOGGED_IN_KEY))
    if user is not None and argon2.verify(old_password, user.password_hash):
        user.password_hash = hashlib.md5(new_password.encode()).hexdigest()
        user.save()
        return True

    return False

