import sqlite3, hashlib

def get_db_conn(db_path='users.db'): return sqlite3.connect(db_path)

def add_user(username, password, db_path='users.db'):
    conn = get_db_conn(db_path)
    pwd_hash = hashlib.md5(password.encode()).hexdigest()
    try:
        conn.execute("INSERT INTO users (username, password) VALUES (?, ?)", (username, pwd_hash))
    except sqlite3.IntegrityError:
        conn.rollback(); conn.close(); return False
    conn.commit(); conn.close(); return True

